# autoCommit 상태 확인
Connection con = dataSource.getConnection();
log.info("autoCommit={}", con.getAutoCommit());
#   autoCommit=true

# 끈다
con.setAutoCommit(false);

# H2 가 받은 것
#   SET AUTOCOMMIT FALSE

# 두 번 수정
con.prepareStatement("update member set money=8000 where member_id='memberA'")
   .executeUpdate();
con.prepareStatement("update member set money=12000 where member_id='memberB'")
   .executeUpdate();

# H2 로그
#   update member set money=8000 where member_id='memberA';
#   update member set money=12000 where member_id='memberB';
#   (commit 이 없다)

# 다른 세션에서 조회
select * from member;
# memberA | 10000
# memberB | 10000

# 아직 옛날 값이다

con.commit();
#   COMMIT

# 다시 조회
# memberA | 8000
# memberB | 12000

# 둘이 같이 바뀌었다
